const rein = $input.first().json;
const roh = rein.body ?? rein;

const UMBRUCH = "\n";

const alsText = (wert) => (wert === null || wert === undefined) ? "" : ("" + wert);

const ohneSteuerzeichen = (wert, zeilenBehalten) => {
  let raus = "";
  for (const zeichen of alsText(wert)) {
    const code = zeichen.charCodeAt(0);
    if (zeilenBehalten && code === 10) { raus += zeichen; continue; }
    raus += (code < 32 || code === 127) ? " " : zeichen;
  }
  return raus;
};

const zusammenziehen = (wert, muster, ersatz) => {
  let raus = wert;
  while (raus.indexOf(muster) !== -1) raus = raus.split(muster).join(ersatz);
  return raus;
};

const einzeilig = (wert, max) =>
  zusammenziehen(ohneSteuerzeichen(wert, false), "  ", " ").trim().slice(0, max);

const mehrzeilig = (wert, max) => {
  const zeilen = ohneSteuerzeichen(wert, true)
    .split(UMBRUCH)
    .map((zeile) => zusammenziehen(zeile, "  ", " ").trim());
  const text = zusammenziehen(zeilen.join(UMBRUCH), UMBRUCH + UMBRUCH + UMBRUCH, UMBRUCH + UMBRUCH);
  return text.trim().slice(0, max);
};

const nurZiffern = (wert) => {
  let raus = "";
  for (const zeichen of alsText(wert)) {
    const code = zeichen.charCodeAt(0);
    if (code >= 48 && code <= 57) raus += zeichen;
  }
  return raus;
};

const emailPlausibel = (wert) => {
  if (wert.indexOf(" ") !== -1) return false;
  const teile = wert.split("@");
  if (teile.length !== 2 || teile[0].length < 1) return false;
  const punkt = teile[1].lastIndexOf(".");
  return punkt >= 1 && (teile[1].length - punkt) >= 3;
};

const istIsoDatum = (wert) =>
  wert.length === 10 && wert.charAt(4) === "-" && wert.charAt(7) === "-" && nurZiffern(wert).length === 8;

const daten = {
  name: einzeilig(roh.name, 120),
  email: einzeilig(roh.email, 200).toLowerCase(),
  telefon: einzeilig(roh.telefon, 40),
  strasse: einzeilig(roh.strasse, 160),
  plz: einzeilig(roh.plz, 10),
  ort: einzeilig(roh.ort, 100),
  anliegen: mehrzeilig(roh.anliegen, 4000)
};

const terminRoh = einzeilig(roh.wunschtermin, 10);
const terminGueltig = istIsoDatum(terminRoh);

const fehler = {};
if (!daten.name) fehler.name = "Bitte geben Sie Ihren Namen an.";
if (!emailPlausibel(daten.email)) fehler.email = "Bitte geben Sie eine gültige E-Mail-Adresse an.";
if (nurZiffern(daten.telefon).length < 6) fehler.telefon = "Bitte geben Sie eine Telefonnummer an, unter der wir Sie erreichen.";
if (!daten.strasse) fehler.strasse = "Bitte geben Sie Straße und Hausnummer an.";
if (daten.plz.length !== 5 || nurZiffern(daten.plz).length !== 5) fehler.plz = "Die Postleitzahl besteht aus fünf Ziffern.";
if (!daten.ort) fehler.ort = "Bitte geben Sie den Ort an.";
if (daten.anliegen.length < 15) fehler.anliegen = "Bitte beschreiben Sie Ihr Anliegen in mindestens einem Satz.";
if (terminRoh.length > 0 && !terminGueltig) fehler.wunschtermin = "Bitte wählen Sie ein Datum aus.";

// Honeypot. Das Feld heißt bewusst nicht "website": Passwort-Manager füllen Felder mit
// diesem Namen auch dann aus, wenn sie per CSS versteckt sind. Ein echter Kunde wäre
// dadurch stillschweigend als Spam ausgesondert worden.
const honeypotGefuellt = alsText(roh.firma_zusatz).trim().length > 0;

const jetzt = new Date();
const berlin = jetzt.toLocaleDateString("sv-SE", { timeZone: "Europe/Berlin" }).split("-");
const laufnummer = Math.floor(Math.random() * 9000) + 1000;
const auftragsnummer = "A-" + berlin[0] + "-" + berlin[1] + berlin[2] + "-" + laufnummer;

const wunschterminText = terminGueltig ? terminRoh : "nicht angegeben";

const promptZeilen = ["Ort: " + daten.ort, "Wunschtermin: " + wunschterminText, "", "Anliegen des Kunden:", daten.anliegen];

let status = "gueltig";
if (honeypotGefuellt) status = "spam";
else if (Object.keys(fehler).length > 0) status = "fehlerhaft";

return [{
  json: {
    status,
    fehler,
    auftragsnummer,
    eingang: jetzt.toISOString(),
    ...daten,
    wunschtermin: terminGueltig ? terminRoh : null,
    wunschterminText,
    promptText: promptZeilen.join(UMBRUCH)
  }
}];

const rein = $input.first().json;
const UMBRUCH = "\n";

const artenErlaubt = ["Rohrbruch / Wasserschaden", "Verstopfung / Abfluss", "Armatur / Sanitärobjekt", "Heizung / Warmwasser", "Neuinstallation / Umbau", "Sonstiges"];
const stufenErlaubt = ["Notfall (heute)", "Diese Woche", "Kann warten"];

let ki = null;
let grund = "";

if (rein.error !== undefined || rein.choices === undefined) {
  grund = "Der Aufruf des Sprachmodells ist fehlgeschlagen.";
} else {
  try {
    const inhalt = rein.choices[0].message.content;
    ki = typeof inhalt === "string" ? JSON.parse(inhalt) : inhalt;
  } catch (ausnahme) {
    grund = "Die Antwort des Sprachmodells war nicht lesbar.";
  }
}

const art = artenErlaubt.includes(ki?.auftragsart) ? ki.auftragsart : null;
const stufe = stufenErlaubt.includes(ki?.dringlichkeit) ? ki.dringlichkeit : null;

if (ki !== null && (art === null || stufe === null)) {
  grund = "Das Sprachmodell hat eine unbekannte Kategorie geliefert.";
}

const geglueckt = art !== null && stufe !== null;

const punkte = geglueckt && Array.isArray(ki.rueckfragen)
  ? ki.rueckfragen.map((frage) => "• " + frage)
  : [];

return [{
  json: {
    analyse: geglueckt ? "OK" : "Fehlgeschlagen",
    auftragsart: art,
    dringlichkeit: stufe,
    zusammenfassung: geglueckt ? ("" + (ki.zusammenfassung ?? "")).slice(0, 200) : "",
    begruendung: geglueckt ? ("" + (ki.begruendung ?? "")).slice(0, 200) : grund,
    rueckfragen: geglueckt
      ? punkte.join(UMBRUCH)
      : "Automatische Einordnung fehlgeschlagen — Anliegen bitte selbst lesen." + UMBRUCH + grund
  }
}];

